--[[
    MUZAN AVATAR EDIT  |  by NOX
    Plays the original-quality edit, but every Muzan shot is replaced by YOUR current avatar
    (whatever outfit / accessories / body colors you're wearing right now).

    Video is embedded in this script. Just execute it (Xeno works).
]]

local FILE_NAME = "nox_muzan_edit_v3.mp4"

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local StarterGui = game:GetService("StarterGui")
local lp = Players.LocalPlayer

local function notify(text)
	pcall(function()
		StarterGui:SetCore("SendNotification", {Title = "NOX EDIT", Text = text, Duration = 5})
	end)
end

-- remove an older copy if executed twice
pcall(function()
	local old = ((gethui and gethui()) or game:GetService("CoreGui")):FindFirstChild("NOXMuzanEdit")
	if old then old:Destroy() end
end)
pcall(function()
	local old = lp.PlayerGui:FindFirstChild("NOXMuzanEdit")
	if old then old:Destroy() end
end)

----------------------------------------------------------------
-- 1) LOAD VIDEO (full-quality original, embedded inside this script)
----------------------------------------------------------------
local getasset = getcustomasset or getsynasset
local EXPECTED_SIZE = 1931992

local function pureDecode(chunks)
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, #alphabet do map[alphabet:byte(i)] = i - 1 end
	local out = {}
	for ci, chunk in ipairs(chunks) do
		local parts = {}
		for i = 1, #chunk, 4 do
			local a, b, c, d = chunk:byte(i, i + 3)
			local n = map[a] * 262144 + map[b] * 4096 + (map[c] or 0) * 64 + (map[d] or 0)
			parts[#parts + 1] = string.char(math.floor(n / 65536) % 256, math.floor(n / 256) % 256, n % 256)
		end
		out[#out + 1] = table.concat(parts)
		if ci % 15 == 0 then task.wait() end
	end
	return table.concat(out)
end

local function decodeB64(chunks)
	-- try the executor's built-in decoder first, but only trust it if the size is exactly right
	local native
	pcall(function()
		native = (crypt and crypt.base64decode) or (crypt and crypt.base64 and (crypt.base64.decode or crypt.base64.decode))
			or base64_decode or (base64 and base64.decode) or (syn and syn.crypt and syn.crypt.base64.decode)
	end)
	if native then
		local okN, res = pcall(function() return native(table.concat(chunks)) end)
		if okN and type(res) == "string" and #res == EXPECTED_SIZE then return res end
	end
	-- fallback: pure Lua decoder (slower but always correct)
	return pureDecode(chunks)
end

