----------------------------------------------------------------
-- 2) CLONE THE EXECUTOR'S AVATAR (current outfit)
----------------------------------------------------------------
local char = lp.Character or lp.CharacterAdded:Wait()
char:WaitForChild("HumanoidRootPart")
task.wait(0.3)

local wasArchivable = char.Archivable
char.Archivable = true
local avatar = char:Clone()
char.Archivable = wasArchivable

if not avatar then
	notify("Couldn't copy your avatar")
	return
end

for _, d in ipairs(avatar:GetDescendants()) do
	if d:IsA("Script") or d:IsA("LocalScript") then
		d:Destroy()
	end
end
for _, d in ipairs(avatar:GetDescendants()) do
	if d:IsA("BasePart") then
		d.Anchored = true
		d.CanCollide = false
	end
end
local hum = avatar:FindFirstChildOfClass("Humanoid")
if hum then
	hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
end

----------------------------------------------------------------
-- 3) GUI
----------------------------------------------------------------
local gui = Instance.new("ScreenGui")
gui.Name = "NOXMuzanEdit"
gui.IgnoreGuiInset = true
gui.ResetOnSpawn = false
gui.DisplayOrder = 999999
gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
pcall(function()
	gui.Parent = (gethui and gethui()) or game:GetService("CoreGui")
end)
if not gui.Parent then
	gui.Parent = lp:WaitForChild("PlayerGui")
end

local back = Instance.new("Frame")
back.Size = UDim2.fromScale(1, 1)
back.BackgroundColor3 = Color3.new(0, 0, 0)
back.BorderSizePixel = 0
back.Parent = gui

-- 9:16 stage (same shape as the original video)
local stage = Instance.new("Frame")
stage.AnchorPoint = Vector2.new(0.5, 0.5)
stage.Position = UDim2.fromScale(0.5, 0.5)
stage.Size = UDim2.fromScale(1, 1)
stage.BackgroundTransparency = 1
stage.ClipsDescendants = true
stage.Parent = back

local ratio = Instance.new("UIAspectRatioConstraint")
ratio.AspectRatio = 720 / 1280
ratio.AspectType = Enum.AspectType.FitWithinMaxSize
ratio.Parent = stage

local video = Instance.new("VideoFrame")
video.Size = UDim2.fromScale(1, 1)
video.BackgroundTransparency = 1
video.Looped = false
video.Volume = 1
video.Video = asset
video.ZIndex = 1
video.Parent = stage

-- the part of the video where the anime footage lives (black bars stay untouched)
local band = Instance.new("Frame")
band.Position = UDim2.fromScale(0, 0.293)
band.Size = UDim2.fromScale(1, 0.415)
band.BackgroundTransparency = 1
band.ClipsDescendants = true
band.ZIndex = 2
band.Visible = false
band.Parent = stage

-- holder = the box where the avatar is drawn (full band or a small box for far shots)
local holder = Instance.new("Frame")
holder.AnchorPoint = Vector2.new(0.5, 0.5)
holder.Position = UDim2.fromScale(0.5, 0.5)
holder.Size = UDim2.fromScale(1, 1)
holder.BackgroundColor3 = Color3.fromRGB(8, 28, 52)
holder.BorderSizePixel = 0
holder.ClipsDescendants = true
holder.ZIndex = 3
holder.Parent = band

local holderCorner = Instance.new("UICorner")
holderCorner.CornerRadius = UDim.new(0, 0)
holderCorner.Parent = holder

-- moving blue "mist" background so the swapped shots keep the same look
local grad = Instance.new("UIGradient")
grad.Color = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromRGB(4, 14, 30)),
	ColorSequenceKeypoint.new(0.5, Color3.fromRGB(18, 70, 120)),
	ColorSequenceKeypoint.new(1, Color3.fromRGB(6, 24, 46)),
})
grad.Parent = holder

local vp = Instance.new("ViewportFrame")
vp.Size = UDim2.fromScale(1, 1)
vp.BackgroundTransparency = 1
vp.Ambient = Color3.fromRGB(150, 170, 215)
vp.LightColor = Color3.fromRGB(210, 225, 255)
vp.LightDirection = Vector3.new(-0.4, -0.8, 0.5)
vp.ZIndex = 4
vp.Parent = holder

avatar.Parent = vp
avatar:PivotTo(CFrame.new(0, 3, 0))

local cam = Instance.new("Camera")
cam.Parent = vp
vp.CurrentCamera = cam

-- close button
local close = Instance.new("TextButton")
close.Size = UDim2.fromOffset(40, 40)
close.Position = UDim2.new(1, -46, 0, 6)
close.BackgroundTransparency = 1
close.Text = "X"
close.TextColor3 = Color3.fromRGB(255, 255, 255)
close.TextTransparency = 0.6
close.TextSize = 22
close.Font = Enum.Font.GothamBold
close.ZIndex = 20
close.Parent = back

----------------------------------------------------------------
-- 4) SHOTS (timed to the original video)
--    Character faces -Z, so a camera at negative Z sees the front.
----------------------------------------------------------------
local V3, CF = Vector3.new, CFrame.lookAt

local shots = {
	-- 0-4s: far shot at the gate (tiny figure)
	{t0 = 0, t1 = 4, box = {pos = UDim2.fromScale(0.42, 0.36), size = UDim2.fromScale(0.22, 0.45), round = true},
		cam = function(p)
			return CF(V3(0.5 - p, 3.6, -15), V3(0, 3, 0)), 32
		end},

	-- 4-8s: foot close-up (side view, stepping)
	{t0 = 4, t1 = 8, bob = true,
		cam = function(p)
			return CF(V3(-4.5 + p * 1.2, 0.9, -2 + p), V3(0, 0.5, -0.2)), 55
		end},

	-- 8-10s: walking with coat flowing (3/4 full body)
	{t0 = 8, t1 = 10, bob = true,
		cam = function(p)
			return CF(V3(-6 + p * 2.5, 3, -8), V3(0, 3.2, 0)), 50
		end},

	-- 10-13s: face close-up (the roar shot), slow push-in
	{t0 = 10, t1 = 13,
		cam = function(p)
			return CF(V3(0, 5.7, -4.6 + p * 1.6), V3(0, 5.5, 0)) * CFrame.Angles(0, 0, math.rad(-6 + p * 6)), 45
		end},

	-- 13-15s: view from above / behind
	{t0 = 13, t1 = 15,
		cam = function(p)
			return CF(V3(0, 12, 6 - p), V3(0, 3, 0)), 50
		end},

	-- 15-18s: legs walking on gravel (from behind)
	{t0 = 15, t1 = 18, bob = true,
		cam = function(p)
			return CF(V3(2 - p, 1.6, 6), V3(0, 1.6, 0)), 55
		end},

	-- 18-22s: feet on the wooden step (floor level)
	{t0 = 18, t1 = 22, bob = true,
		cam = function(p)
			return CF(V3(-5, 0.6, -0.8 + p * 1.2), V3(0, 0.4, 0)), 55
		end},

	-- 22-26s: far shot, standing by the water
	{t0 = 22, t1 = 26, box = {pos = UDim2.fromScale(0.30, 0.44), size = UDim2.fromScale(0.20, 0.48), round = true},
		cam = function(p)
			return CF(V3(0.5 - p * 0.5, 3.6, -15), V3(0, 3, 0)), 32
		end},

	-- 26-end: portrait close-up (the final pose), slow push-in
	{t0 = 26, t1 = 99,
		cam = function(p, t)
			local push = math.clamp((t - 26) / 4, 0, 1)
			return CF(V3(0, 5, -6 + push * 1.6), V3(0, 4.7, 0)), 40
		end},
}

local current
local function applyShot(s)
	current = s
	if s.box then
		holder.Position = s.box.pos
		holder.Size = s.box.size
		holderCorner.CornerRadius = UDim.new(1, 0)
	else
		holder.Position = UDim2.fromScale(0.5, 0.5)
		holder.Size = UDim2.fromScale(1, 1)
		holderCorner.CornerRadius = UDim.new(0, 0)
	end
end

----------------------------------------------------------------
-- 5) PLAY
----------------------------------------------------------------
local conn
local function cleanup()
	if conn then conn:Disconnect() end
	pcall(function() video:Stop() end)
	gui:Destroy()
end

close.MouseButton1Click:Connect(cleanup)
video.Ended:Connect(function()
	task.wait(0.6)
	cleanup()
end)

notify("Loading edit...")
local waited = 0
while not video.IsLoaded and waited < 40 do
	task.wait(0.2)
	waited += 0.2
end
if not video.IsLoaded then
	local sz = "?"
	pcall(function() sz = tostring(#readfile(FILE_NAME)) end)
	notify("Video didn't load (file size " .. sz .. "). Tell me which executor you use.")
	cleanup()
	return
end
band.Visible = true

video.TimePosition = 0
video:Play()

applyShot(shots[1])
conn = RunService.RenderStepped:Connect(function()
	local t = video.TimePosition
	local shot = shots[#shots]
	for _, s in ipairs(shots) do
		if t >= s.t0 and t < s.t1 then
			shot = s
			break
		end
	end
	if shot ~= current then
		applyShot(shot)
	end

	local p = math.clamp((t - shot.t0) / (shot.t1 - shot.t0), 0, 1)
	local cf, fov = shot.cam(p, t)
	cam.CFrame = cf
	cam.FieldOfView = fov

	local bob = shot.bob and math.abs(math.sin(t * 7)) * 0.18 or 0
	avatar:PivotTo(CFrame.new(0, 3 + bob, 0))

	grad.Rotation = (t * 25) % 360
end)
